import React,{useCallback,useEffect,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,ArrowDownToLine,ArrowRight,BarChart3,Bell,Bolt,Check,CheckCheck,ChevronDown,ChevronRight,CircleAlert,CircleCheck,Clock3,CloudUpload,Clapperboard,Copy,ExternalLink,Eye,FileVideo,FolderOpen,Gauge,HardDrive,LayoutDashboard,Link2,Search,LoaderCircle,LockKeyhole,MessageSquare,MonitorPlay,MoreVertical,Pause,Play,Plus,Radio,RefreshCw,Scissors,Send,Settings2,ShieldCheck,SlidersHorizontal,Sparkles,Trash2,Upload,Video,Wifi,WifiOff,X,Youtube} from 'lucide-react';
import * as api from './api';
import type {Channel,Device,Highlight,Settings,Snapshot,Tab,UpdateStatus} from './api';
import './style.css';
import './redesign.css';
import './visual-refresh.css';
const NAV:[Tab,string,React.ElementType][]=[['dashboard','Обзор',LayoutDashboard],['streams','Стримеры',Radio],['highlights','Моменты',Scissors],['studio','Видеостудия',Clapperboard],['publishing','Публикация',CloudUpload],['settings','Настройки',Settings2]];
const LIBRARY_FILTERS=[['all','Все'],['ready','Готовые'],['pending','В обработке']] as const;
const initial:Snapshot={settings:{auto_publish:false,auto_publish_confirmed:false,auto_targets:[],auto_youtube_privacy:'private',auto_tiktok_mode:'MEDIA_UPLOAD',auto_daily_limit:5,client_id:'',demo_mode:true,auto_clip:false,auto_export:false,threshold:68,cooldown_seconds:120,output_dir:'',banner_path:'',ffmpeg_path:'ffmpeg',vision_endpoint:'https://api.openai.com/v1/chat/completions',vision_model:''},channels:[],highlights:[],monitoring:false,authenticated_as:null};
type Account=api.ConnectedAccount & {selected:boolean};
function titleStatus(status:string){return ({detected:'Обнаружен',creating:'Twitch обрабатывает',clip_ready:'Клип создан',downloaded:'Файл загружен',source_attached:'Исходник готов',exported:'Готов к публикации',clip_timeout:'Таймаут Twitch',published_youtube:'YouTube загружен',tiktok_draft:'Черновик TikTok'} as Record<string,string>)[status]||status;}
function timeAgo(ts:string){const seconds=Math.max(0,Math.floor((Date.now()-new Date(ts).getTime())/1000));if(seconds<60)return 'только что';if(seconds<3600)return `${Math.floor(seconds/60)} мин назад`;if(seconds<86400)return `${Math.floor(seconds/3600)} ч назад`;return new Date(ts).toLocaleDateString('ru-RU')}
function Button({children,onClick,disabled,kind='primary',icon:Icon,loading=false,type='button',className=''}:{children:React.ReactNode;onClick?:()=>void;disabled?:boolean;kind?:'primary'|'secondary'|'ghost'|'danger';icon?:React.ElementType;loading?:boolean;type?:'button'|'submit';className?:string}){return <button type={type} disabled={disabled||loading} onClick={onClick} className={`btn btn-${kind} ${className}`}>{loading?<LoaderCircle size={16} className="spin"/>:Icon?<Icon size={16}/>:null}{children}</button>}
function SectionTitle({name,sub,action}:{name:string;sub?:string;action?:React.ReactNode}){return <div className="section-head"><div><h2>{name}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>}
function Empty({icon:Icon,text,sub}:{icon:React.ElementType;text:string;sub:string}){return <div className="empty"><div className="empty-icon"><Icon size={25}/></div><strong>{text}</strong><span>{sub}</span></div>}
function CheckToggle({checked,onChange,label,sub}:{checked:boolean;onChange:(b:boolean)=>void;label:string;sub?:string}){return <label className="toggle-line"><span><strong>{label}</strong>{sub&&<small>{sub}</small>}</span><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/><span className="switch"/></label>}
function HighlightCard({h,selected,onPick}:{h:Highlight;selected?:boolean;onPick:(h:Highlight)=>void}){return <button onClick={()=>onPick(h)} className={`moment-card ${selected?'selected':''}`}><div className="moment-thumb"><div className="moment-thumb-circle"><Play size={20} fill="currentColor"/></div><span className="moment-length">{h.length} сек</span></div><div className="moment-info"><div className="moment-user"><span className="round-avatar">{h.channel_login[0]?.toUpperCase()||'C'}</span><span>{h.channel_login}</span><span className="dotsep">•</span><span>{timeAgo(h.detected_at)}</span></div><strong>{h.title}</strong><div className="moment-meta"><span className={`mini-status ${h.output_path?'ready':''}`}>{titleStatus(h.status)}</span><span>{h.explanation||'Всплеск активности'}</span></div></div><div className="moment-score"><strong>{h.score}</strong><span>AI score</span></div><ChevronRight className="muted" size={18}/></button>}

function SignalTimeline({highlights}:{highlights:Highlight[]}){
 const recent=[...highlights].sort((a,b)=>new Date(a.detected_at).getTime()-new Date(b.detected_at).getTime()).slice(-12);
 const dots=recent.map((h,i)=>({x:recent.length===1?160:22+i*(276/(recent.length-1)),y:120-Math.max(0,Math.min(100,h.score))}));
 const path=dots.map((p,i)=>`${i?'L':'M'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');
 return <div className="signal-widget">
  <div className="signal-head"><div className="signal-symbol"><Activity size={18}/></div><div><strong>Активность детектора</strong><span>Рейтинги последних {recent.length} событий</span></div><span className="signal-legend"><i/>AI score</span></div>
  {recent.length?<div className="signal-plot"><svg viewBox="0 0 320 142" role="img" aria-label="График рейтингов последних событий"><defs><linearGradient id="signalFill" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#916bff" stopOpacity=".35"/><stop offset="1" stopColor="#916bff" stopOpacity="0"/></linearGradient></defs><path d="M 12 20 H 308 M 12 64 H 308 M 12 108 H 308" stroke="#353846" strokeDasharray="3 6" fill="none"/><path d={`${path} L ${dots.at(-1)!.x} 138 L ${dots[0].x} 138 Z`} fill="url(#signalFill)"/><path d={path} stroke="#a88aff" strokeWidth="3" fill="none" strokeLinecap="round" strokeLinejoin="round"/>{dots.map((p,i)=><circle key={i} cx={p.x} cy={p.y} r="4" stroke="#181923" strokeWidth="2" fill="#c9bcff"/>)}</svg><div className="signal-axis"><span>Более ранние</span><span>Последние события</span></div></div>:<div className="signal-no-data"><Activity size={30}/><strong>Пока нет данных</strong><span>После обнаружения событий здесь появится их рейтинг.</span></div>}
 </div>
}

function App(){
 const [tab,setTab]=useState<Tab>('dashboard');const [data,setData]=useState<Snapshot>(initial);
 const [streamQuery,setStreamQuery]=useState('');const [libraryFilter,setLibraryFilter]=useState<'all'|'ready'|'pending'>('all');
 const [settings,setSettings]=useState<Settings>(initial.settings);const [addName,setAddName]=useState('');const [adding,setAdding]=useState(false);
 const [selected,setSelected]=useState<number|null>(null);const [toast,setToast]=useState<{message:string;kind:'good'|'bad'}|null>(null);
 const [pending,setPending]=useState('');const [device,setDevice]=useState<Device|null>(null);const [visionKey,setVisionKey]=useState('');
 const [accounts,setAccounts]=useState<Account[]>([]);const [updateStatus,setUpdateStatus]=useState<UpdateStatus|null>(null);const [checkingUpdate,setCheckingUpdate]=useState(false);
 const notifiedUpdateVersion=useRef<string|null>(null);
 const [integrations,setIntegrations]=useState<api.IntegrationDiagnostics|null>(null);const [checkingIntegrations,setCheckingIntegrations]=useState(false);
 const [updatePanelOpen,setUpdatePanelOpen]=useState(false);const [updateInstalling,setUpdateInstalling]=useState(false);
 const [updateProgress,setUpdateProgress]=useState<api.UpdateProgress|null>(null);
 const [publishTitle,setPublishTitle]=useState('');const [privacy,setPrivacy]=useState('private');const [publishAgreed,setPublishAgreed]=useState(false);
 const [hostedKey,setHostedKey]=useState('');const [hostedProfile,setHostedProfile]=useState('clipforge');const [hostedReady,setHostedReady]=useState(false);
 const [githubToken,setGithubToken]=useState('');const [githubReady,setGithubReady]=useState(false);
 const [publishResults,setPublishResults]=useState<Record<string,api.PublishResult>>({});
 const inform=useCallback((message:string,kind:'good'|'bad'='good')=>setToast({message,kind}),[]);
 const refresh=useCallback(async()=>{try{const [s,linked]=await Promise.all([api.getSnapshot(),api.connectedAccounts()]);setData(s);setSettings(s.settings);setAccounts(old=>linked.map(item=>({...item,selected:old.find(o=>o.id===item.id)?.selected??false})));}catch(err){inform(String(err),'bad')}},[inform]);
 useEffect(()=>{void refresh();let cleanup:(()=>void)|undefined;void api.watchRefresh(()=>{void refresh()},(s)=>inform(s,'bad'),(s)=>inform(s,'good')).then(un=>cleanup=un);return()=>cleanup?.()},[refresh,inform]);
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(null),8000);return()=>clearTimeout(id)},[toast]);
 useEffect(()=>{let stop:(()=>void)|undefined;void api.watchUpdateProgress(p=>setUpdateProgress(p)).then(un=>stop=un);return()=>stop?.()},[]);
 useEffect(()=>{let stop:(()=>void)|undefined;void api.watchPublishProgress(p=>setPublishResults(prev=>({...prev,[p.account_id]:p}))).then(un=>stop=un);return()=>stop?.()},[]);
 useEffect(()=>{if(api.desktop){
  void api.integrationDiagnostics().then(setIntegrations).catch(()=>{});
  void api.hostedStatus().then(p=>setHostedReady(p.connected)).catch(()=>{});
  void api.githubUpdateTokenStatus().then(setGithubReady).catch(()=>{});
 }},[]);
 useEffect(()=>{if(!device)return;let running=true;const t=setInterval(()=>{void api.pollDevice().then(user=>{if(user&&running){setDevice(null);inform(`Twitch подключён: ${user.display_name}`);void refresh()}}).catch(e=>{if(running){setDevice(null);inform(String(e),'bad')}})},Math.max(5,device.interval)*1000);return()=>{running=false;clearInterval(t)}},[device,inform,refresh]);
 const run=useCallback(async(key:string,fn:()=>Promise<unknown>,success?:string)=>{setPending(key);try{await fn();if(success)inform(success);await refresh()}catch(err){inform(err instanceof Error?err.message:String(err),'bad')}finally{setPending('')}},[inform,refresh]);
 const current=data.highlights.find(h=>h.id===selected)||data.highlights[0]||null;
 const visibleChannels=data.channels.filter(c=>`${c.display_name} ${c.login}`.toLocaleLowerCase().includes(streamQuery.trim().toLocaleLowerCase()));
 const visibleHighlights=data.highlights.filter(h=>libraryFilter==='all'||(libraryFilter==='ready'?!!h.output_path:!h.output_path));
 const libraryCurrent=visibleHighlights.find(h=>h.id===selected)||visibleHighlights[0]||null;
 const active=data.channels.filter(c=>c.enabled).length;
 const ready=data.highlights.filter(h=>h.output_path).length;
 const maxScore=Math.max(0,...data.highlights.map(h=>h.score));
 const authReady=!!data.authenticated_as;
 const update=(field:keyof Settings,value:string|number|boolean)=>setSettings(p=>({...p,[field]:value}));
 const save=()=>run('save',()=>api.saveSettings(settings),'Настройки сохранены');
 const chooseBanner=async()=>{try{const path=await api.pickFile([{name:'Изображения',extensions:['png','jpg','jpeg','webp']}]);if(path)update('banner_path',path)}catch(e){inform(String(e),'bad')}};
 const chooseDir=async()=>{try{const path=await api.pickDirectory();if(path)update('output_dir',path)}catch(e){inform(String(e),'bad')}};
 const attach=async()=>{if(!current)return;try{const path=await api.pickFile([{name:'Видео',extensions:['mp4','mov','mkv','webm']}]);if(path)await run('attach',()=>api.attachVideo(current.id,path),'Исходник прикреплён')}catch(e){inform(String(e),'bad')}};
 const start=()=>run('monitor',()=>data.monitoring?api.stopMonitor():api.startMonitor(),data.monitoring?'Мониторинг остановлен':'Мониторинг включён');
 const publishAll=async()=>{if(!current||!current.output_path)return inform('Сначала экспортируй видео','bad');if(!publishAgreed)return inform('Подтверди права и загрузку','bad');
 const targets=accounts.filter(a=>a.selected);if(!targets.length)return inform('Выбери хотя бы один подключённый аккаунт','bad');
 if(targets.length>20)return inform('Можно выбрать не больше 20 аккаунтов за одну отправку','bad');
 setPublishResults(Object.fromEntries(targets.map(a=>[a.id,{account_id:a.id,account_name:a.name,platform:a.platform,state:'queued' as const,detail:'В очереди'}])));
 setPending('publish');try{
  const results=await api.publishBatch(current.id,targets.map(a=>a.id),publishTitle.trim()||current.title,privacy,true);
  setPublishResults(Object.fromEntries(results.map(result=>[result.account_id,result])));
  const ok=results.filter(r=>r.state==='success'||r.state==='draft').length;
  inform(`Загрузка завершена: ${ok} из ${results.length}. Проверь результаты каждого аккаунта.`,ok?'good':'bad');
  await refresh();
 }catch(e){inform(String(e),'bad')}finally{setPending('')}
 };
 const selectGroup=(platform:'youtube'|'tiktok'|'all',selected:boolean)=>setAccounts(prev=>prev.map(a=>platform==='all'||a.platform===platform?{...a,selected}:a));
 const connectTwitch=()=>run('device',async()=>{await api.saveSettings(settings);const d=await api.beginDevice();setDevice(d);await api.externalUrl(d.verification_uri)},'Открыта авторизация Twitch; код для подтверждения показан в настройках');
 const connectYouTube=()=>run('youtube',async()=>{const url=await api.beginYouTube();await api.externalUrl(url)},'Открыта авторизация YouTube в браузере');
 const connectTikTok=()=>run('tiktok',async()=>{const url=await api.beginTikTok();await api.externalUrl(url)},'Открыта авторизация TikTok в браузере');
 const saveHostedKey=()=>run('hosted-key',async()=>{await api.hostedSaveKey(hostedKey);setHostedKey('');setHostedReady(true)},'Upload-Post подключён; ключ хранится в Windows Credential Manager');
 const forgetHostedKey=()=>run('hosted-forget',async()=>{await api.hostedForgetKey();setHostedReady(false)},'Ключ Upload-Post удалён из Windows');
 const connectHosted=()=>run('hosted-connect',async()=>{const url=await api.hostedConnect(hostedProfile.trim());await api.externalUrl(url)},'Открыта официальная страница подключения YouTube / TikTok в Upload-Post');
 const saveGithubToken=()=>run('github-token',async()=>{await api.githubUpdateTokenSave(githubToken);setGithubToken('');setGithubReady(true);const status=await api.checkUpdates();setUpdateStatus(status)},'GitHub OTA настроен: токен хранится в Windows Credential Manager');
 const forgetGithubToken=()=>run('github-forget',async()=>{await api.githubUpdateTokenForget();setGithubReady(false)},'Доступ GitHub OTA отключён');
 const autoToggleTarget=(id:string,checked:boolean)=>setSettings(p=>({...p,auto_targets:checked?[...new Set([...p.auto_targets,id])]:p.auto_targets.filter(x=>x!==id)}));
 const checkForUpdates=async()=>{setCheckingUpdate(true);try{const status=await api.checkUpdates();setUpdateStatus(status);if(status.available)setUpdatePanelOpen(true);else inform(status.message)}catch(e){inform(String(e),'bad')}finally{setCheckingUpdate(false)}};
 const openUpdates=()=>{setUpdatePanelOpen(true);void checkForUpdates()};
 const installLatestUpdate=async()=>{if(!updateStatus?.can_install){void api.externalUrl(updateStatus?.release_url||'https://github.com/apollo-170/GTA6inTTandYT/releases');return}setUpdateInstalling(true);setUpdateProgress({stage:'Подготовка скачивания',percent:0});try{await api.installUpdate();inform('Установщик запускается. Подтверди обновление Windows.')}catch(e){setUpdateInstalling(false);inform(String(e),'bad')}};
 const openTwitchShare=(h:Highlight)=>{if(!h.clip_url){inform('Сначала создай Twitch-клип. Для публикации в YouTube Shorts и TikTok открой готовый клип и выбери «Поделиться».','bad');return}void api.externalUrl(h.clip_url)};
 useEffect(()=>{if(!api.desktop)return;let enabled=true;const check=()=>{void api.checkUpdates().then(status=>{if(!enabled)return;if(status.available&&status.latest_version!==notifiedUpdateVersion.current){notifiedUpdateVersion.current=status.latest_version;setUpdatePanelOpen(true);inform('Доступна версия ClipForge '+status.latest_version)}setUpdateStatus(status)}).catch(()=>{})};check();const interval=setInterval(check,30*60*1000);const focus=()=>check();window.addEventListener('focus',focus);return()=>{enabled=false;clearInterval(interval);window.removeEventListener('focus',focus)}},[inform]);
 const checkConnections=async()=>{setCheckingIntegrations(true);try{setIntegrations(await api.integrationDiagnostics());inform('Проверка подключений завершена')}catch(e){inform(String(e),'bad')}finally{setCheckingIntegrations(false)}};
 const typeBadge=api.desktop?'Windows / Tauri':'Веб-предпросмотр';
 const featureList=useMemo(()=>[{icon:MessageSquare,text:'Мониторинг чата',detail:'EventSub WebSocket'},{icon:Bolt,text:'Умный детектор',detail:'Анализ всплесков'},{icon:Video,text:'Формат Shorts',detail:'FFmpeg · 9:16'},{icon:Upload,text:'Публикация',detail:'YouTube + TikTok Draft'}],[]);

 return <div className="app-shell"><aside className="sidebar">
  <div className="brand"><span className="brand-logo"><Play fill="white" size={21}/></span><div><b>ClipForge</b><small>AI CLIP STUDIO</small></div><span className="brand-version">v0.7.0</span></div>
  <div className="nav-label">НАВИГАЦИЯ</div><nav className="navigation">{NAV.map(([value,label,Icon])=><button key={value} className={`nav-item ${tab===value?'active':''}`} onClick={()=>setTab(value)}><Icon size={19}/><span>{label}</span>{value==='highlights'&&data.highlights.length>0&&<i>{data.highlights.length}</i>}</button>)}</nav>
  <div className="sidebar-bottom"><div className="side-summary"><span className="status-dot"/><span><b>{data.monitoring?'Детектор включён':'Детектор остановлен'}</b><small>{data.monitoring?'Ожидание событий Twitch':'Готов к работе'}</small></span></div><div className="sidebar-tip"><div className="tip-mark"><Sparkles size={17}/></div><span><b>AI Highlight Studio</b><small>Создавай вертикальные ролики из лучших моментов.</small></span></div><div className="sidebar-footer"><span className="avatar-small">CF</span><span><b>Локальная студия</b><small>{typeBadge}</small></span><MoreVertical size={17}/></div></div>
 </aside>
 <main className="main"><header className="topbar"><div className="breadcrumbs">Рабочая область <ChevronRight size={14}/> <strong>{NAV.find(n=>n[0]===tab)?.[1]}</strong></div><div className="top-controls"><span className="local-badge"><span className="status-dot"/>{data.monitoring?'Мониторинг активен':api.desktop?'Desktop Engine':'Демо интерфейса'}</span><button className="icon-button" title="Обновить данные" aria-label="Обновить данные" onClick={()=>void refresh()}><RefreshCw size={18}/></button><button className={updateStatus?.available?'icon-button update-bell has-update':'icon-button update-bell'} title="Центр обновлений" aria-label="Центр обновлений" onClick={openUpdates}><Bell size={18}/>{updateStatus?.available&&<span className="notification-mark"/>}</button><button className="icon-button" title="Настройки" onClick={()=>setTab('settings')}><Settings2 size={18}/></button></div></header>
 <div className="content">
 {updateStatus?.available&&<div className="update-banner"><div><Bell size={20}/><span><b>Новая версия ClipForge {updateStatus.latest_version}</b><small>Новая версия готова к установке.</small></span></div><Button icon={ArrowDownToLine} kind="secondary" onClick={()=>setUpdatePanelOpen(true)}>Обновить</Button></div>}
 {tab==='dashboard'&&<>
  <div className="welcome studio-hero"><div className="hero-copy">
   <div className="eyebrow"><span className="live-dot"/> CLIPFORGE WORKSPACE</div>
   <h1>Лучшие моменты<br/><span>без лишней рутины.</span></h1>
   <p>Подключай Twitch-каналы, отслеживай реакцию чата и готовь короткие ролики в одной студии.</p>
   <div className="welcome-actions"><Button icon={data.monitoring?Pause:Play} onClick={start} loading={pending==='monitor'}>{data.monitoring?'Остановить детектор':'Запустить детектор'}</Button><Button kind="secondary" icon={Plus} onClick={()=>setTab('streams')}>Добавить стримера</Button></div>
   <div className="hero-footnote"><ShieldCheck size={13}/> Только разрешённые клипы <i/> Twitch Clip до 60 секунд</div>
   </div><div className="hero-console">
    <div className="hero-console-top"><span><Activity size={16}/> СОСТОЯНИЕ СТУДИИ</span><span className={data.monitoring?'status-chip live':'status-chip'}>{data.monitoring?'Активна':'Ожидание'}</span></div>
    <div className="hero-console-score"><span>Мониторинг</span><strong>{data.monitoring?'В эфире':'Не запущен'}</strong><small>{authReady?'Twitch подключён':'Подключи Twitch для настоящего мониторинга'}</small></div>
    <div className="hero-console-stats"><div><strong>{active.toString().padStart(2,'0')}</strong><span>Каналов</span></div><div><strong>{data.highlights.length.toString().padStart(2,'0')}</strong><span>Моментов</span></div><div><strong>{ready.toString().padStart(2,'0')}</strong><span>Экспортов</span></div></div>
    <button className="hero-console-link" onClick={()=>setTab('highlights')}>Открыть библиотеку <ArrowRight size={15}/></button>
   </div></div>
  <div className="stat-grid"><div className="stat-card"><div className="stat-icon purple"><Radio size={20}/></div><div className="stat-label">Отслеживается</div><div className="stat-value">{active.toString().padStart(2,'0')}<span>каналов</span></div><div className="stat-foot"><Activity size={14}/> Twitch EventSub</div></div><div className="stat-card"><div className="stat-icon green"><Scissors size={20}/></div><div className="stat-label">Моментов найдено</div><div className="stat-value">{data.highlights.length.toString().padStart(2,'0')}<span>событий</span></div><div className="stat-foot"><Sparkles size={14}/> AI-поиск</div></div><div className="stat-card"><div className="stat-icon blue"><Video size={20}/></div><div className="stat-label">Готовые ролики</div><div className="stat-value">{ready.toString().padStart(2,'0')}<span>файлов</span></div><div className="stat-foot"><Check size={14}/> Для публикации</div></div><div className="stat-card"><div className="stat-icon orange"><Gauge size={20}/></div><div className="stat-label">Максимальный рейтинг</div><div className="stat-value">{maxScore}<span>/ 100</span></div><div className="stat-foot"><Bolt size={14}/> Оценка момента</div></div></div>
  <div className="dashboard-insights"><SignalTimeline highlights={data.highlights}/><div className="workflow-callout"><div className="workflow-icon"><Sparkles size={23}/></div><div className="workflow-title"><span>ГОТОВ К РАБОТЕ</span><strong>Твой следующий клип начинается здесь</strong><p>Добавь Twitch-канал и запусти детектор. Готовые моменты попадут в библиотеку.</p></div><Button kind="secondary" icon={ArrowRight} onClick={()=>setTab(active?'highlights':'streams')}>{active?'Открыть моменты':'Добавить стримера'}</Button></div></div>
  <div className="dashboard-columns"><section className="panel"><SectionTitle name="Активные стримеры" sub="Список каналов под наблюдением" action={<button className="text-action" onClick={()=>setTab('streams')}>Все каналы <ArrowRight size={15}/></button>}/>{data.channels.length===0?<Empty icon={Radio} text="Пока нет каналов" sub="Добавь первый Twitch-канал, чтобы начать"/>:<div className="channel-list">{data.channels.slice(0,5).map(c=><div className="channel-row" key={c.id}><div className="stream-avatar">{c.display_name.charAt(0).toUpperCase()}<span className={`live-mark ${c.enabled?'on':''}`}/></div><div className="grow"><strong>{c.display_name}</strong><span>twitch.tv/{c.login}</span></div><span className={`state-pill ${c.enabled?'live':'off'}`}>{c.enabled?'Отслеживается':'Пауза'}</span></div>)}</div>}</section>
  <section className="panel"><SectionTitle name="Последние моменты" sub="Автоматически найденные события" action={<button className="text-action" onClick={()=>setTab('highlights')}>Все моменты <ArrowRight size={15}/></button>}/>{data.highlights.length===0?<Empty icon={Scissors} text="Пока пусто" sub="Найденные клипы появятся здесь"/>:<div className="recent-list">{data.highlights.slice(0,4).map(h=><button key={h.id} className="recent-row" onClick={()=>{setSelected(h.id);setTab('highlights')}}><span className="recent-spark"><Bolt size={17}/></span><span className="grow"><b>{h.channel_login}</b><small>{timeAgo(h.detected_at)} · {h.length} секунд</small></span><span className="recent-score">{h.score}/100</span><ChevronRight size={16} className="muted"/></button>)}</div>}</section></div>
  <section className="panel pipeline"><SectionTitle name="Твой конвейер контента" sub="От трансляции до готового Shorts за несколько автоматизированных шагов"/><div className="feature-grid">{featureList.map(({icon:Icon,text,detail},i)=><React.Fragment key={text}><div className="feature"><div className="feature-icon"><Icon size={22}/></div><b>{text}</b><small>{detail}</small></div>{i<featureList.length-1&&<ArrowRight size={16} className="feature-arrow"/>}</React.Fragment>)}</div></section>
 </>}
 {tab==='streams'&&<><div className="page-head"><div><span className="eyebrow">TWITCH SOURCES</span><h1>Управление стримерами</h1><p>Подключай каналы и управляй обнаружением ярких моментов.</p></div><div className="page-actions"><Button icon={data.monitoring?Pause:Play} loading={pending==='monitor'} onClick={start}>{data.monitoring?'Остановить':'Начать отслеживание'}</Button></div></div>
 <section className="panel add-panel"><form onSubmit={e=>{e.preventDefault();setAdding(true);void run('add',()=>api.addChannel(addName),'Канал добавлен').finally(()=>{setAdding(false);setAddName('')})}} className="add-row"><span className="input-leading"><Radio size={18}/></span><input placeholder="Ник Twitch-стримера (например, shroud)" value={addName} onChange={e=>setAddName(e.target.value)}/><Button type="submit" icon={Plus} disabled={!addName.trim()} loading={adding}>Добавить канал</Button></form><p className="helper"><CircleAlert size={14}/> При активном мониторинге после добавления канала перезапусти подключение, чтобы подписаться на его чат.</p></section>
 <div className="list-toolbar"><SectionTitle name={`Стримеры (${data.channels.length})`} sub="Управляй источниками и разрешениями для клипов"/><label className="search-box"><Search size={17}/><input value={streamQuery} onChange={e=>setStreamQuery(e.target.value)} placeholder="Поиск канала..." aria-label="Поиск Twitch-канала"/>{streamQuery&&<button type="button" aria-label="Очистить поиск" onClick={()=>setStreamQuery('')}><X size={14}/></button>}</label></div>
 {data.channels.length===0?<div className="panel"><Empty icon={MonitorPlay} text="Ещё нет ни одного стримера" sub="Введи ник сверху и нажми «Добавить канал»."/></div>:visibleChannels.length===0?<div className="panel"><Empty icon={Search} text="Каналы не найдены" sub="Попробуй другой поисковый запрос."/></div>:<div className="stream-grid">{visibleChannels.map(c=><div className="stream-card" key={c.id}><div className="stream-head"><div className="stream-big-avatar">{c.display_name[0]?.toUpperCase()}</div><div className="grow"><strong>{c.display_name}</strong><small>@{c.login}</small></div><button className="icon-button danger-hover" title="Удалить" onClick={()=>run('delete',()=>api.removeChannel(c.id),'Канал удалён')}><Trash2 size={17}/></button></div><div className="stream-lines"><div><span><MessageSquare size={15}/> Сообщений с запуска</span><b>{c.messages.toLocaleString('ru-RU')}</b></div><div><span><Sparkles size={15}/> Режим</span><b>{c.id.startsWith('demo:')?'Демо':'EventSub'}</b></div></div><div className="stream-options"><CheckToggle checked={c.enabled} label="Отслеживать канал" onChange={v=>void run('update',()=>api.updateChannel(c.id,v,c.rights_confirmed))}/><CheckToggle checked={c.rights_confirmed} label="Есть разрешение на клипы" sub="Право создавать и использовать контент" onChange={v=>void run('update',()=>api.updateChannel(c.id,c.enabled,v))}/></div><Button kind="secondary" icon={ExternalLink} className="full" onClick={()=>void api.externalUrl(`https://www.twitch.tv/${encodeURIComponent(c.login)}`)}>Открыть Twitch</Button></div>)}</div>}
 <div className="info-banner"><ShieldCheck size={19}/><div><b>Права на контент</b><p>Для автоматического скачивания и публикации нужен доступ владельца/редактора канала и разрешение на повторное использование видео. Переключатель не выдаёт права через Twitch.</p></div></div>
 </>}
 {tab==='highlights'&&<><div className="page-head"><div><span className="eyebrow">AI HIGHLIGHTS</span><h1>Найденные моменты</h1><p>Все события, которые детектор выделил в Twitch-чате.</p></div><div className="page-actions"><span className="neutral-pill">{data.highlights.length} в библиотеке</span><Button kind="secondary" icon={Bolt} disabled={!data.channels.length||!data.settings.demo_mode} onClick={()=>run('burst',api.demoBurst,'Создан тестовый всплеск')}>Тестовый всплеск</Button></div></div>
 {data.settings.demo_mode&&<div className="info-banner"><Sparkles size={19}/><div><b>Активен демонстрационный режим</b><p>Добавь стримера, запусти мониторинг и нажми «Тестовый всплеск», чтобы проверить логику без API.</p></div></div>}
 <div className="library-layout"><section className="panel library-list"><SectionTitle name="Библиотека" sub="Клипы и найденные события"/><div className="filter-tabs" role="group" aria-label="Фильтр моментов">{LIBRARY_FILTERS.map(([value,label])=><button key={value} className={libraryFilter===value?'active':''} aria-pressed={libraryFilter===value} onClick={()=>setLibraryFilter(value)}>{label}{value==='all'?<span>{data.highlights.length}</span>:null}</button>)}</div>{visibleHighlights.length===0?<Empty icon={Clapperboard} text={data.highlights.length?'Нет моментов с таким статусом':'Моменты не найдены'} sub={data.highlights.length?'Выбери другой фильтр':'Запусти детектор и дождись события'}/>:visibleHighlights.map(h=><HighlightCard key={h.id} h={h} selected={h.id===libraryCurrent?.id} onPick={x=>setSelected(x.id)}/>)}</section><section className="panel detail-panel"><SectionTitle name="Карточка момента" sub="Подробности и действия"/>{libraryCurrent?<><div className="clip-preview"><Play size={40} fill="currentColor"/><span>TWITCH HIGHLIGHT</span></div><h3>{libraryCurrent.title}</h3><div className="detail-table"><div><span>Канал</span><strong>@{libraryCurrent.channel_login}</strong></div><div><span>Длительность</span><strong>{libraryCurrent.length} секунд</strong></div><div><span>AI-рейтинг</span><strong className="accent-text">{libraryCurrent.score}/100</strong></div><div><span>Статус</span><strong>{titleStatus(libraryCurrent.status)}</strong></div></div><div className="explanation"><Sparkles size={17}/><span>{libraryCurrent.explanation||'Событие обнаружено по реакциям аудитории.'}</span></div><div className="button-stack">{libraryCurrent.clip_url&&<Button icon={Send} kind="secondary" onClick={()=>openTwitchShare(libraryCurrent)}>Поделиться клипом через Twitch</Button>}<Button icon={Scissors} loading={pending==='clip'} disabled={libraryCurrent.channel_id.startsWith('demo:')} onClick={()=>run('clip',()=>api.createClip(libraryCurrent.id),'Twitch-клип создан')}>Создать Twitch Clip (до 60 с)</Button><Button icon={ArrowRight} kind="secondary" onClick={()=>{setSelected(libraryCurrent.id);setTab('studio')}}>Открыть в видеостудии</Button></div></>:<Empty icon={Scissors} text="Выбери момент" sub="Здесь появятся детали выбранного события"/>}</section></div></>}
 {tab==='studio'&&<><div className="page-head"><div><span className="eyebrow">VERTICAL VIDEO ENGINE</span><h1>Видеостудия</h1><p>Превращай разрешённые клипы в вертикальные ролики с фирменным стилем.</p></div><Button kind="secondary" icon={FolderOpen} onClick={()=>void chooseDir()}>Выбрать папку экспорта</Button></div><div className="studio-grid"><section className="panel"><SectionTitle name="Выбранный момент" sub="История источников и экспорт"/>{current?<><div className="select-wrap"><select value={current.id} onChange={e=>setSelected(Number(e.target.value))}>{data.highlights.map(h=><option key={h.id} value={h.id}>{h.channel_login} — {timeAgo(h.detected_at)} · {h.score}/100</option>)}</select><ChevronDown size={16}/></div><div className="current-clip"><div className="current-clip-icon"><FileVideo size={24}/></div><div className="grow"><b>{current.title}</b><small>{current.source_path?'Исходный файл готов':'Нет исходного видео'} · {current.length} сек</small></div></div><label className="field-label">Источник MP4 / MOV / MKV / WEBM</label><div className="path-field"><span title={current.source_path||''}>{current.source_path||'Видео ещё не выбрано'}</span><button className="input-button" title="Выбрать файл" onClick={()=>void attach()}><FolderOpen size={18}/></button></div><div className="button-stack"><Button icon={Video} disabled={!current.source_path} loading={pending==='render'} onClick={()=>run('render',()=>api.renderVideo(current.id),'Вертикальное видео готово')}>Сделать вертикальное видео</Button>{current.output_path&&<div className="success-note"><CircleCheck size={18}/><div><b>Экспорт завершён</b><small>{current.output_path}</small></div></div>}</div><div className="subsection"><div className="subsection-title"><Eye size={18}/><b>Визуальный AI-анализ</b></div><p>Анализирует кадр доступного видео через настроенную Vision-модель. Ключ передаётся только для запроса и не сохраняется.</p><input type="password" placeholder="API key Vision-модели" value={visionKey} onChange={e=>setVisionKey(e.target.value)}/><Button kind="secondary" icon={Sparkles} disabled={!current.source_path||!settings.vision_model||!visionKey} loading={pending==='vision'} onClick={()=>run('vision',()=>api.analyzeVideo(current.id,visionKey),'Визуальная оценка обновлена')}>Анализировать кадр</Button></div></>:<Empty icon={FileVideo} text="Нет выбранного момента" sub="Создай тестовое событие или включи мониторинг"/>}</section>
 <section className="panel"><SectionTitle name="Шаблон Shorts" sub="Визуальная композиция будущего видео"/><div className="preview-stage"><div className="phone"><div className="phone-top">ТВОЙ БАННЕР</div><div className="phone-media"><div><Play size={29} fill="currentColor"/></div><span>GAMEPLAY</span></div><div className="phone-caption">НАСТОЯЩИЙ ХАЙЛАЙТ 🔥</div><div className="phone-bottom">@YOUR_CHANNEL</div></div><div className="preview-desc"><span className="format-tag">9:16</span><h3>1080 × 1920</h3><p>Фон размывается, оригинальное видео помещается по центру, сверху накладывается пользовательский баннер.</p><div className="preview-property"><Check size={15}/> H.264 / AAC</div><div className="preview-property"><Check size={15}/> 30 FPS</div><div className="preview-property"><Check size={15}/> Ограничение Twitch: 60 с</div></div></div><div className="subsection"><label className="field-label">PNG/JPEG баннер (сверху)</label><div className="path-field"><span>{settings.banner_path||'Без баннера'}</span><button className="input-button" onClick={()=>void chooseBanner()}><FolderOpen size={18}/></button></div><Button icon={Check} kind="secondary" onClick={save} loading={pending==='save'}>Сохранить шаблон</Button></div></section></div></>}
 {tab==='publishing'&&<><div className="page-head"><div><span className="eyebrow">SOCIAL DISTRIBUTION</span><h1>Публикация роликов</h1><p>Подключай аккаунты через официальную авторизацию, без ручного ввода токенов.</p></div><span className="neutral-pill">Публикация с подтверждением</span></div><div className="automation-deck">
<section className="panel hosted-connector"><SectionTitle name="Подключение соцсетей без собственного сервера" sub="Upload-Post Cloud · несколько TikTok и YouTube-аккаунтов"/>
 <div className="hosted-status"><span className={hostedReady?'hosted-led connected':'hosted-led'}/><strong>{hostedReady?'API-ключ защищён и сохранён на Windows':'Добавь API-ключ Upload-Post один раз'}</strong></div>
 <p className="helper">Создай API-ключ в своём Upload-Post, сохрани здесь и подключай соцсети через официальный браузер. Клиентский ключ не вшивается в EXE, не сохраняется в SQLite и не отправляется на GitHub.</p>
 <div className="hosted-entry"><input type="password" autoComplete="off" placeholder="Upload-Post API key (локально в Windows)" value={hostedKey} onChange={e=>setHostedKey(e.target.value)}/><Button icon={LockKeyhole} loading={pending==='hosted-key'} disabled={!hostedKey.trim()} onClick={()=>void saveHostedKey()}>Сохранить ключ</Button></div>
 <div className="connect-list"><Button kind="secondary" icon={ExternalLink} onClick={()=>void api.externalUrl('https://app.upload-post.com/')}>Кабинет Upload-Post</Button>{hostedReady&&<Button kind="ghost" onClick={()=>void forgetHostedKey()}>Отключить ключ</Button>}</div>
 <div className="hosted-linker"><label className="field-label">Профиль публикации (для каждого TikTok-аккаунта используй отдельное имя)</label><div className="hosted-entry"><input value={hostedProfile} onChange={e=>setHostedProfile(e.target.value)} placeholder="Например: clipforge_1"/><Button kind="secondary" icon={Link2} loading={pending==='hosted-connect'} disabled={!hostedReady||!hostedProfile.trim()} onClick={()=>void connectHosted()}>Подключить TikTok / YouTube</Button></div></div>
 <div className="connect-list"><Button kind="secondary" icon={RefreshCw} onClick={()=>void refresh()}>Обновить список аккаунтов</Button></div>
 <p className="helper">Для TikTok нужен тариф Upload-Post с TikTok. В режиме DIRECT_POST сервис может публиковать напрямую, если аккаунт и разрешения платформы это поддерживают. Иначе выбери черновики.</p>
</section>
<section className="panel automation-control"><SectionTitle name="Полный автоматический конвейер" sub="Twitch → официальный MP4 → FFmpeg Shorts → выбранные профили"/>
 <CheckToggle checked={settings.auto_clip} onChange={v=>update('auto_clip',v)} label="1. Автоматически находить и создавать клипы" sub="Только каналы с разрешением на использование видео"/>
 <CheckToggle checked={settings.auto_export} onChange={v=>update('auto_export',v)} label="2. Автоматически монтировать Shorts" sub="Скачать Twitch Clip и обработать в FFmpeg"/>
 <CheckToggle checked={settings.auto_publish} onChange={v=>setSettings(p=>({...p,auto_publish:v,auto_publish_confirmed:v?false:p.auto_publish_confirmed}))} label="3. Автоматически загружать на соцсети" sub="После экспорта без дополнительных нажатий, пока программа запущена"/>
 <label className="field-label">Аккаунты для автопубликации</label>
 <div className="auto-targets">{accounts.filter(a=>a.id.startsWith('up:')).map(a=><label key={a.id} className="auto-target"><input type="checkbox" checked={settings.auto_targets.includes(a.id)} onChange={e=>autoToggleTarget(a.id,e.target.checked)}/><span className="grow"><b>{a.name}</b><small>{a.platform==='tiktok'?'TikTok':'YouTube'}</small></span></label>)}{accounts.filter(a=>a.id.startsWith('up:')).length===0&&<p className="batch-empty">Сначала подключи аккаунты через Upload-Post слева, потом отметь их для автоматической загрузки.</p>}</div>
 <div className="auto-options"><label><span>Режим TikTok</span><select value={settings.auto_tiktok_mode} onChange={e=>update('auto_tiktok_mode',e.target.value)}><option value="MEDIA_UPLOAD">Черновики (подтвердить в TikTok)</option><option value="DIRECT_POST">Прямая публикация (если разрешена)</option></select></label><label><span>Видимость YouTube</span><select value={settings.auto_youtube_privacy} onChange={e=>update('auto_youtube_privacy',e.target.value)}><option value="private">Private</option><option value="unlisted">Unlisted</option><option value="public">Public</option></select></label><label><span>Максимум автоклипов / 24 часа</span><input type="number" min="1" max="20" value={settings.auto_daily_limit} onChange={e=>update('auto_daily_limit',Number(e.target.value))}/></label></div>
 <label className="consent"><input type="checkbox" checked={settings.auto_publish_confirmed} onChange={e=>update('auto_publish_confirmed',e.target.checked)}/><span>Я владею этим видео либо имею право автоматически размещать его во всех выбранных аккаунтах и понимаю выбранную видимость публикации.</span></label>
 <Button icon={Check} loading={pending==='save'} onClick={()=>void save()}>Сохранить настройки автоматики</Button>
 <p className="helper">Автоматизация работает на этом ПК, пока ClipForge открыт, Twitch подключён и мониторинг запущен. Ролик не публикуется, если нет прав на канал, разрешения Twitch на скачивание или доступного аккаунта. Для проверки начни с Private/Draft.</p>
</section></div><div className="publish-grid"><section className="panel twitch-share-panel"><SectionTitle name="Публикация через Twitch" sub="Официальное меню Twitch: YouTube Shorts, TikTok и другие соцсети"/><div className="twitch-native-flow"><div className="twitch-native-number">1</div><span>Создай Twitch Clip, открой его через ClipForge и выбери кнопку «Поделиться» на Twitch. При необходимости сначала свяжи соцсети в настройках Twitch.</span></div><div className="connect-list"><Button icon={Send} disabled={!current?.clip_url} onClick={()=>current&&openTwitchShare(current)}>Открыть клип и поделиться</Button>{!current?.clip_url&&current&&!current.channel_id.startsWith('demo:')&&<Button kind="secondary" icon={Scissors} loading={pending==='clip'} onClick={()=>run('clip',()=>api.createClip(current.id),'Клип создан. Открой его после обработки Twitch.')}>Создать Twitch Clip</Button>}<Button icon={Link2} kind="secondary" onClick={()=>void api.externalUrl('https://www.twitch.tv/settings/connections')}>Связанные аккаунты Twitch</Button></div><p className="helper">{current?.clip_url?'Готовый Twitch-клип можно публиковать через встроенное меню Twitch.':'Выбери или создай настоящий Twitch Clip в библиотеке. Демо-события в соцсети не публикуются.'} Этот способ запускает публикацию в браузере, а не автоматически нажимает кнопки Twitch. Доступность публикации чужого клипа зависит от настроек автора.</p></section><section className="panel"><SectionTitle name="Подключённые аккаунты" sub="Браузерная авторизация · без передачи токенов интерфейсу"/><div className="connect-list"><Button icon={Radio} kind="secondary" loading={pending==='device'} onClick={()=>{if(authReady){setTab('settings');return}setTab('settings');void connectTwitch()}}>{authReady?'Twitch подключён':'Войти через Twitch'}</Button><Button icon={Youtube} loading={pending==='youtube'} kind="secondary" onClick={connectYouTube}>Войти через YouTube</Button><Button icon={Video} kind="secondary" loading={pending==='tiktok'} onClick={connectTikTok}>Добавить TikTok-аккаунт</Button><Button kind="secondary" icon={ExternalLink} onClick={()=>void api.externalUrl('https://www.twitch.tv/settings/connections')}>TikTok через Twitch</Button></div><p className="helper">YouTube можно подключить несколько раз для разных каналов. TikTok подключается через сервер OAuth ClipForge, который должен быть настроен владельцем приложения. С разрешением video.upload ролик попадёт в черновики TikTok; прямые публичные посты требуют отдельного одобрения video.publish.</p>
 <div className="account-selection-toolbar"><strong>{accounts.filter(a=>a.selected).length} из {accounts.length} аккаунтов выбрано</strong><div className="account-selection-actions"><button onClick={()=>selectGroup('all',true)}>Выбрать все</button><button onClick={()=>selectGroup('all',false)}>Снять выбор</button></div></div>
 <div className="batch-platform-head"><span><Youtube size={16}/> YouTube <b>{accounts.filter(a=>a.platform==='youtube').length}</b></span><div><button onClick={()=>selectGroup('youtube',true)}>Выбрать</button><button onClick={()=>selectGroup('youtube',false)}>Снять</button></div></div>
 <div className="account-list">{accounts.filter(a=>a.platform==='youtube').map(a=><div key={a.id} className={'account batch-account '+(a.selected?'picked':'')}><label className="checkbox"><input checked={a.selected} type="checkbox" onChange={e=>setAccounts(p=>p.map(x=>x.id===a.id?{...x,selected:e.target.checked}:x))}/></label><span className="account-icon youtube"><Youtube size={21}/></span><div className="grow"><b>{a.name}</b><small>Канал YouTube {publishResults[a.id]?'· '+publishResults[a.id].detail:'· подключён'}</small></div>{publishResults[a.id]&&<span className={'job-pill '+publishResults[a.id].state}>{({queued:'В очереди',uploading:'Загрузка',success:'Готово',draft:'Черновик',error:'Ошибка'} as Record<string,string>)[publishResults[a.id].state]}</span>}<button className="icon-button danger-hover" title={a.id.startsWith('up:')?'Отключение в Upload-Post':'Отключить'} disabled={pending==='publish'||a.id.startsWith('up:')} onClick={()=>void run('logout',()=>api.removeAccount(a.id),'YouTube отключён')}><X size={17}/></button></div>)}{accounts.filter(a=>a.platform==='youtube').length===0&&<p className="batch-empty">Добавь YouTube-каналы кнопкой выше. Каждый вход авторизует выбранный канал.</p>}</div>
 <div className="batch-platform-head"><span><Video size={16}/> TikTok <b>{accounts.filter(a=>a.platform==='tiktok').length}</b></span><div><button onClick={()=>selectGroup('tiktok',true)}>Выбрать</button><button onClick={()=>selectGroup('tiktok',false)}>Снять</button></div></div>
 <div className="account-list">{accounts.filter(a=>a.platform==='tiktok').map(a=><div key={a.id} className={'account batch-account '+(a.selected?'picked':'')}><label className="checkbox"><input checked={a.selected} type="checkbox" onChange={e=>setAccounts(p=>p.map(x=>x.id===a.id?{...x,selected:e.target.checked}:x))}/></label><span className="account-icon tiktok"><Video size={21}/></span><div className="grow"><b>{a.name}</b><small>{publishResults[a.id]?.detail||'TikTok · отправка в черновики'}</small></div>{publishResults[a.id]&&<span className={'job-pill '+publishResults[a.id].state}>{({queued:'В очереди',uploading:'Загрузка',success:'Готово',draft:'Черновик',error:'Ошибка'} as Record<string,string>)[publishResults[a.id].state]}</span>}<button className="icon-button danger-hover" title={a.id.startsWith('up:')?'Отключение в Upload-Post':'Отключить'} disabled={pending==='publish'||a.id.startsWith('up:')} onClick={()=>void run('logout',()=>api.removeAccount(a.id),'TikTok отключён')}><X size={17}/></button></div>)}{accounts.filter(a=>a.platform==='tiktok').length===0&&<p className="batch-empty">Для прямого подключения нужен настроенный TikTok OAuth Bridge и разрешение video.upload. До этого можно публиковать вручную через Twitch.</p>}</div></section>
 <section className="panel"><SectionTitle name="Отправить видео" sub="Выбор ролика и подтверждение отправки"/><label className="field-label">Готовый ролик</label><div className="select-wrap"><select value={current?.id||''} onChange={e=>{const h=data.highlights.find(h=>h.id===Number(e.target.value));setSelected(h?.id??null);setPublishTitle(h?.title||'')}}>{data.highlights.length===0?<option value="">Нет готовых видео</option>:data.highlights.map(h=><option value={h.id} key={h.id}>{h.channel_login} · {h.output_path?'готов':'нет экспорта'}</option>)}</select><ChevronDown size={16}/></div>{current?.output_path?<div className="success-note"><CheckCheck size={19}/><span>Видео готово к загрузке</span></div>:<div className="info-banner compact"><CircleAlert size={16}/><span>Сначала сделай экспорт во вкладке «Видеостудия».</span></div>}<label className="field-label">Название</label><input value={publishTitle} placeholder={current?.title||'Название ролика'} onChange={e=>setPublishTitle(e.target.value)}/><label className="field-label">Видимость YouTube</label><select value={privacy} onChange={e=>setPrivacy(e.target.value)}><option value="private">Private (безопасный тест)</option><option value="unlisted">Unlisted</option><option value="public">Public</option></select><label className="consent"><input type="checkbox" checked={publishAgreed} onChange={e=>setPublishAgreed(e.target.checked)}/><span>Подтверждаю право публиковать этот контент и разрешаю отправку на выбранные аккаунты.</span></label><Button icon={Send} loading={pending==='publish'} disabled={!current?.output_path||!accounts.some(a=>a.selected)||!publishAgreed} className="full" onClick={()=>void publishAll()}>Отправить на {accounts.filter(a=>a.selected).length} аккаунтов</Button>{Object.keys(publishResults).length>0&&<div className="batch-results"><strong>Результаты отправки</strong>{Object.values(publishResults).map(r=><div className={'batch-result '+r.state} key={r.account_id}><span className={'job-pill '+r.state}>{({queued:'В очереди',uploading:'Загрузка',success:'Загружен',draft:'Черновик',error:'Ошибка'} as Record<string,string>)[r.state]}</span><div><b>{r.account_name}</b><small>{r.detail}</small></div></div>)}</div>}<p className="helper">YouTube: прямое размещение через Google API на каждом выбранном канале. TikTok: загрузка в черновики каждого профиля через одобренный video.upload; опубликовать черновик нужно в TikTok. Каждая попытка показывает отдельный результат, без повторного клика и без автоматических дублей.</p></section></div></>}
 {tab==='settings'&&<><div className="page-head"><div><span className="eyebrow">CONTROL CENTER</span><h1>Настройки ClipForge</h1><p>Аккаунты, детектор, обработка видео и обновления.</p></div><Button icon={Check} onClick={save} loading={pending==='save'}>Сохранить настройки</Button></div><div className="settings-grid"><section className="panel"><SectionTitle name="Twitch" sub="Официальная авторизация без ручного ввода токенов"/><div className="auth-box"><div><span className={`auth-indicator ${authReady?'connected':''}`}><LockKeyhole size={17}/></span><span><b>{authReady?`Подключено: ${data.authenticated_as}`:'Twitch не подключён'}</b><small>{authReady?'Авторизация активна':'Войди для мониторинга чата Twitch'}</small></span></div>{authReady?<Button kind="secondary" onClick={()=>run('disconnect',api.disconnect,'Twitch отключён')}>Отключить</Button>:<Button kind="secondary" icon={Link2} loading={pending==='device'} onClick={connectTwitch}>Войти через Twitch</Button>}</div>{device&&<div className="device-box"><p>На официальной странице Twitch подтверди доступ по коду:</p><strong>{device.user_code}</strong><Button kind="ghost" icon={Copy} onClick={()=>void navigator.clipboard?.writeText(device.user_code)}>Скопировать код</Button><small>После подтверждения ClipForge подключится автоматически.</small></div>}<CheckToggle checked={settings.demo_mode} onChange={v=>update('demo_mode',v)} label="Демонстрационный режим" sub="Проверка без Twitch API"/><p className="helper">Client ID приложения настраивает разработчик при сборке. Пользователю не нужно вводить Client ID, пароли и токены.</p></section>
 <section className="panel integration-panel"><SectionTitle name="Диагностика подключений" sub="Показывает, какие интеграции реально настроены в этой версии"/><div className="integration-rows">{[
 {name:'Twitch API',ready:integrations?.twitch_configured,detail:integrations?.twitch_configured?(integrations.twitch_connected?'Вход выполнен':'Кнопка входа готова'):'Нужен Twitch Client ID разработчика'},
 {name:'YouTube API',ready:integrations?.youtube_configured,detail:integrations?.youtube_configured?(integrations.youtube_accounts?'Подключено каналов: '+integrations.youtube_accounts:'Кнопка входа готова'):'Нужен Google OAuth Desktop Client ID'},
 {name:'TikTok',ready:integrations?.tiktok_configured,detail:'Нужны сервер OAuth и согласование TikTok API'},
 {name:'FFmpeg',ready:integrations?.ffmpeg_ready,detail:integrations?.ffmpeg_ready?'Готов к монтажу':'Проверь наличие ffmpeg.exe в комплекте'},
 {name:'Обновления',ready:integrations?.update_feed_public,detail:'Репозиторий закрыт: релизы доступны через браузер'}
 ].map(item=><div key={item.name} className="integration-row"><span className={item.ready?'integration-dot good':'integration-dot pending'}/><div><strong>{item.name}</strong><small>{item.detail}</small></div><span className={item.ready?'integration-state good':'integration-state pending'}>{item.ready?'Готово':integrations?'Нужно настроить':'Не проверено'}</span></div>)}</div><div className="connect-list"><Button kind="secondary" icon={RefreshCw} loading={checkingIntegrations} onClick={()=>void checkConnections()}>Проверить подключения</Button><Button kind="secondary" icon={ExternalLink} onClick={()=>void api.externalUrl('https://github.com/apollo-170/GTA6inTTandYT/settings/variables/actions')}>Настройка разработчика</Button></div><p className="helper">Это параметры самого ClipForge. Пароли и токены пользователей сюда вводить не нужно.</p></section>
 <section className="panel"><SectionTitle name="Детектор моментов" sub="Баланс между чувствительностью и количеством клипов"/><label className="field-label">Порог срабатывания <b className="accent-text">{settings.threshold}/100</b></label><input type="range" min="30" max="95" step="1" value={settings.threshold} onChange={e=>update('threshold',Number(e.target.value))}/><div className="range-labels"><span>Чаще</span><span>Только лучшие моменты</span></div><label className="field-label top-gap">Пауза между событиями (сек)</label><input type="number" min="15" max="3600" value={settings.cooldown_seconds} onChange={e=>update('cooldown_seconds',Number(e.target.value))}/><CheckToggle checked={settings.auto_clip} onChange={v=>update('auto_clip',v)} label="Автоматически создавать Twitch-клип" sub="Только для каналов с разрешением; длина ≤ 60 с"/><CheckToggle checked={settings.auto_export} onChange={v=>update('auto_export',v)} label="Экспорт после разрешённой загрузки" sub="Если Twitch предоставит доступ владельца или редактора"/></section>
 <section className="panel"><SectionTitle name="Экспорт видео" sub="Папка, баннер и FFmpeg"/><label className="field-label">Путь к FFmpeg</label><input value={settings.ffmpeg_path} onChange={e=>update('ffmpeg_path',e.target.value)} placeholder="ffmpeg или полный путь к ffmpeg.exe"/><label className="field-label">Папка для экспорта</label><div className="path-field"><span>{settings.output_dir||'Видео / ClipForge'}</span><button className="input-button" onClick={()=>void chooseDir()}><FolderOpen size={18}/></button></div><label className="field-label">Баннер (PNG, JPG)</label><div className="path-field"><span>{settings.banner_path||'Без баннера'}</span><button className="input-button" onClick={()=>void chooseBanner()}><FolderOpen size={18}/></button></div><div className="info-banner compact"><HardDrive size={16}/><span>Кодирование выполняется локально через FFmpeg, без загрузки видео на внешние серверы.</span></div></section>
 <section className="panel"><SectionTitle name="Vision AI" sub="Дополнительная оценка кадров из разрешённых клипов"/><label className="field-label">OpenAI-совместимый endpoint</label><input value={settings.vision_endpoint} onChange={e=>update('vision_endpoint',e.target.value)} placeholder="https://api.../v1/chat/completions"/><label className="field-label">Имя Vision-модели</label><input value={settings.vision_model} onChange={e=>update('vision_model',e.target.value)} placeholder="Название мультимодальной модели"/><div className="info-banner compact"><Eye size={16}/><span>Этот модуль анализирует кадр готового видео. Непрерывный live-анализ изображения потребует отдельного разрешённого видеовхода.</span></div></section><section className="panel update-settings"><SectionTitle name="Обновления ClipForge" sub="Официальные Windows-установщики в GitHub Releases"/><div className="version-status"><RefreshCw size={22}/><div><b>Текущая версия: {updateStatus?.current_version||'0.7.0'}</b><small>{updateStatus?.message||'Проверь наличие обновлений'}</small></div></div><div className="connect-list"><Button kind="secondary" icon={RefreshCw} loading={checkingUpdate} onClick={()=>void checkForUpdates()}>Проверить обновления</Button><Button kind="secondary" icon={Bell} onClick={()=>setUpdatePanelOpen(true)}>Центр обновлений</Button><Button kind="secondary" icon={ExternalLink} onClick={()=>void api.externalUrl(updateStatus?.release_url||'https://github.com/apollo-170/GTA6inTTandYT/releases')}>GitHub Releases</Button>{updateStatus?.available&&<Button icon={ArrowDownToLine} onClick={()=>setUpdatePanelOpen(true)}>Обновить сейчас</Button>}</div><p className="helper">ClipForge проверяет версии при запуске, возвращении в окно и каждые 30 минут. Когда релиз доступен публично, приложение скачает установщик, проверит SHA-256 и предложит обновление. Пока GitHub-репозиторий закрыт, переходи в Releases через браузер.</p></section></div></>}
 </div></main>{updatePanelOpen&&<div className="upgrade-overlay" role="presentation" onClick={()=>{if(!updateInstalling)setUpdatePanelOpen(false)}}><div className="upgrade-modal" role="dialog" aria-modal="true" aria-label="Центр обновлений" onClick={e=>e.stopPropagation()}><div className="upgrade-modal-top"><div className="upgrade-modal-icon"><RefreshCw size={23}/></div><button className="icon-button" aria-label="Закрыть" disabled={updateInstalling} onClick={()=>setUpdatePanelOpen(false)}><X size={19}/></button></div><span className="upgrade-kicker">CLIPFORGE UPDATES</span><h2>{updateStatus?.available?'Доступна версия '+updateStatus.latest_version:'Центр обновлений'}</h2><p>{updateStatus?.message||'Проверь наличие новой версии ClipForge на GitHub.'}</p><div className="upgrade-versions"><span>Установлено <strong>v{updateStatus?.current_version||'0.7.0'}</strong></span><ArrowRight size={17}/><span>Последняя <strong>{updateStatus?.latest_version?'v'+updateStatus.latest_version:'Не определена'}</strong></span></div>{updateInstalling&&<div className="upgrade-download"><div><strong>{updateProgress?.stage||'Подготовка обновления'}</strong><small>{updateProgress?.percent||0}%</small></div><div className="upgrade-track"><div style={{width:(updateProgress?.percent||0)+'%'}}/></div><small>Не закрывай ClipForge до запуска установщика.</small></div>}<div className="upgrade-actions"><Button icon={updateStatus?.available?ArrowDownToLine:RefreshCw} loading={updateInstalling||checkingUpdate} onClick={()=>{if(updateStatus?.available)void installLatestUpdate();else void checkForUpdates()}}>{updateStatus?.available?(updateStatus.can_install?'Скачать и установить':'Открыть релиз'):'Проверить версию'}</Button><Button kind="secondary" icon={ExternalLink} disabled={updateInstalling} onClick={()=>void api.externalUrl(updateStatus?.release_url||'https://github.com/apollo-170/GTA6inTTandYT/releases')}>Открыть GitHub</Button></div><small className="upgrade-footnote"><ShieldCheck size={13}/> Запуск установки только после подтверждения. SHA-256 сверяется с данными GitHub.</small></div></div>}{toast&&<div className={`toast ${toast.kind}`}><span>{toast.kind==='good'?<CircleCheck size={19}/>:<CircleAlert size={19}/>}</span><span>{toast.message}</span><button onClick={()=>setToast(null)}><X size={15}/></button></div>}</div>
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
